const COPIES = 3;          // three identical copies of the row make the loop seamless on any width
const DWELL_S = 2.2;       // seconds each logo spends zoomed in the spotlight at the centre
const EASE = [0.22, 1, 0.36, 1];

function TechLogo({ tech }) {
  return (
    <svg
      className="tw-svg"
      viewBox={tech.viewBox}
      fill={tech.color}
      aria-hidden="true"
      focusable="false"
    >
      <path d={tech.path} />
    </svg>
  );
}

export default function TechnologyShowcase() {
  const reduce = useReducedMotion();
  const viewportRef = useRef(null);
  const trackRef = useRef(null);
  const hoverRef = useRef(false);

  // Marquee + sequential zoom, driven by ONE position value so they can never drift apart:
  // the row travels right to left, and whichever logo is crossing the centre "spotlight"
  // is the one that zooms in. Logos therefore zoom one by one, in order, forever.
  useEffect(() => {
    if (reduce) return undefined;
    const viewport = viewportRef.current;
    const track = trackRef.current;
    if (!viewport || !track) return undefined;

    const items = Array.from(track.children);
    const N = TECHS.length;

    let slot = items[0].getBoundingClientRect().width; // width of one logo cell
    let cx = viewport.clientWidth / 2;                // spotlight = horizontal centre
    let p = N * slot + slot / 2;                      // position of the spotlight along the row
    let activeEl = null;
    let raf = 0;
    let last = 0;
    let visible = false;

    const apply = (snap) => {
      track.style.transform = `translate3d(${-(p - cx)}px, 0, 0)`;
      const next = items[Math.floor(p / slot)] || null;
      if (next === activeEl) return;
      if (snap) track.classList.add('tw-snap'); // no transition for the invisible loop reset
      if (activeEl) activeEl.classList.remove('is-active');
      if (next) next.classList.add('is-active');
      activeEl = next;
      if (snap) {
        // force the style change to apply instantly, then re-enable transitions
        void track.offsetWidth;
        track.classList.remove('tw-snap');
      }
    };

    const tick = (now) => {
      raf = 0;
      if (!visible) return;
      const dt = Math.min((now - (last || now)) / 1000, 0.1); // clamp: no jump after a hidden tab
      last = now;
      if (!hoverRef.current) {
        p += (slot / DWELL_S) * dt;
        let snap = false;
        // reset by exactly one row length, in the middle of a logo's hold, so it is invisible
        if (p >= 2 * N * slot + slot / 2) {
          p -= N * slot;
          snap = true;
        }
        apply(snap);
      }
      raf = requestAnimationFrame(tick);
    };

    const start = () => {
      if (!raf && visible) {
        last = 0;
        raf = requestAnimationFrame(tick);
      }
    };

    apply(false);

    const io = new IntersectionObserver(
      ([entry]) => {
        visible = entry.isIntersecting;
        if (visible) start();
        else if (raf) {
          cancelAnimationFrame(raf);
          raf = 0;
        }
      },
      { threshold: 0.05 }
    );
    io.observe(viewport);

    const ro = new ResizeObserver(() => {
      const newSlot = items[0].getBoundingClientRect().width;
      if (newSlot && newSlot !== slot) {
        p = (p / slot) * newSlot;
        slot = newSlot;
      }
      cx = viewport.clientWidth / 2;
      apply(false);
    });
    ro.observe(viewport);

    return () => {
      if (raf) cancelAnimationFrame(raf);
      io.disconnect();
      ro.disconnect();
    };
  }, [reduce]);

  const rise = {
    hidden: { opacity: 0, y: reduce ? 0 : 24 },
    visible: (d = 0) => ({
      opacity: 1,
      y: 0,
      transition: { duration: reduce ? 0.15 : 0.7, ease: EASE, delay: reduce ? 0 : d },
    }),
  };
  const view = { once: true, amount: 0.3 };

  const copies = reduce ? 1 : COPIES;

  return (
    <section className="tw" id="technologies" aria-labelledby="tw-title">
      <div className="tw-bg" aria-hidden="true" />

      <div className="tw-inner">
        <header className="tw-header">
          <motion.div className="tw-eyebrow" variants={rise} custom={0} initial="hidden" whileInView="visible" viewport={view}>
            <span className="tw-eyebrow-line" aria-hidden="true" />
            <span>OUR TECHNOLOGY</span>
          </motion.div>

          <motion.h2 id="tw-title" className="tw-title" variants={rise} custom={0.1} initial="hidden" whileInView="visible" viewport={view}>
            Technologies We <span className="tw-accent">Build With</span>
          </motion.h2>

          <motion.p className="tw-desc" variants={rise} custom={0.2} initial="hidden" whileInView="visible" viewport={view}>
            Our developers use modern, reliable technologies to build scalable websites, powerful
            applications, and seamless digital experiences.
          </motion.p>

          <span className="tw-rule" aria-hidden="true" />
        </header>

        <motion.div
          className={`tw-stage${reduce ? ' is-static' : ''}`}
          variants={rise}
          custom={0.3}
          initial="hidden"
          whileInView="visible"
          viewport={view}
          onPointerEnter={() => (hoverRef.current = true)}
          onPointerLeave={() => (hoverRef.current = false)}
        >
          <div className="tw-viewport" ref={viewportRef}>
            <ul className="tw-track" ref={trackRef} aria-label="Technologies we use">
              {Array.from({ length: copies }).flatMap((_, c) =>
                TECHS.map((tech) => (
                  <li
                    key={`${c}-${tech.name}`}
                    className="tw-item"
                    aria-hidden={c > 0 ? 'true' : undefined}
                  >
                    <span className="tw-logo">
                      <TechLogo tech={tech} />
                    </span>
                    <span className="tw-name">{tech.name}</span>
                  </li>
                ))
              )}
            </ul>
          </div>
        </motion.div>
      </div>
    </section>
  );
}